"""Agrega a las preguntas del paquete formato-icfes su hoja completa (marcas, pasos, enfoque, guion de 3 niveles)."""
import json
P='content/packs/formato-icfes.json'
d=json.load(open(P)); Q={q['id']:q for q in d['preguntas']}
def M(frag,rol,nota,campo): return {"frag":frag,"rol":rol,"nota":nota,"campo":campo}
def B(t,a=None,k=None):
    b={"t":t}
    if a: b["a"]=a
    if k: b["k"]=k
    return b
def put(i,modo,marcas,pasos,que,tema,pistas,clave,no,plan,g1,g2,g3):
    Q[i]['hoja']={"modo":modo,"marcas":marcas,"pasos":pasos,"enfoque":{"tema":tema,"que":que,"pistas":pistas,"clave":clave,"no":[{"t":a,"p":b} for a,b in no],"plan":[{"t":t,**({"eq":e} if e else {})} for t,e in plan]},"guion":{"1":g1,"2":g2,"3":g3}}
dias=["Lun","Mar","Mié","Jue","Vie"]; ar=[40,55,30,70,85]
barr=lambda res:{"k":"barras","titulo":"Las ventas de la semana, barra por barra","barras":[{"l":x,"e":str(v),"segs":[{"v":v,"c":"verde" if x==res else "azul"}]} for x,v in zip(dias,ar)],"nota":"Ya no hay que adivinar: la barra más larga es la que más vendió."} 
